// Calculate tomorrow's date for reminder filtering
const now = new Date();

// Calculate tomorrow
const tomorrow = new Date(now);
tomorrow.setDate(tomorrow.getDate() + 1);

// Format date for Google Sheets (MM/DD/YYYY)
const formatDate = (date) => {
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  const year = date.getFullYear();
  return `${month}/${day}/${year}`;
};

const tomorrowDate = formatDate(tomorrow);

return {
  json: {
    now: now.toISOString(),
    tomorrow: tomorrow.toISOString(),
    tomorrowDate: tomorrowDate,
    reminderTime: '6:00 PM'
  }
};

// Filter appointments that need form completion reminders
const appointments = $input.all();
const tomorrowDate = $('Calculate Tomorrow\'s Date').first().json.tomorrowDate;

const needsReminder = [];

for (const item of appointments) {
  const apt = item.json;

  // Skip if no date or status
  if (!apt.Date || !apt.Status) continue;

  // Parse appointment date
  const aptDate = apt.Date;

  // Check conditions for sending reminder:
  // 1. Appointment is tomorrow
  // 2. Status is SCHEDULED
  // 3. Form link was sent (Form_Link_Sent = "Yes")
  // 4. Form NOT completed (Form_Completed is not "Yes")
  // 5. Patient has phone number
  // 6. Reminder not already sent today (Reminder_Sent is not "Yes")

  const isTomorrow = aptDate === tomorrowDate;
  const isScheduled = apt.Status === 'SCHEDULED';
  const formSent = apt.Form_Link_Sent === 'Yes';
  const formNotCompleted = apt.Form_Completed !== 'Yes';
  const hasPhone = apt.Phone && apt.Phone.trim() !== '';
  const reminderNotSent = apt.Reminder_Sent !== 'Yes';

  if (isTomorrow && isScheduled && formSent && formNotCompleted && hasPhone && reminderNotSent) {
    // Get form link from sheet (saved when form was sent)
    const formLink = apt.Form_Completion_Link || '';

    needsReminder.push({
      json: {
        ...apt,
        formLink: formLink
      }
    });
  }
}

if (needsReminder.length === 0) {
  // No appointments need reminders
  console.log('✅ No intake form reminders needed for tomorrow');
  return [];
}

console.log(`📋 ${needsReminder.length} patients need intake form reminders for tomorrow`);
return needsReminder;
